package co.fcv.citas.appointment;
import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.Authentication;
@RestController @RequestMapping("/api/v1/admin/specialized-requests") public class SpecializedRequestAdminController { private final JdbcTemplate db; public SpecializedRequestAdminController(JdbcTemplate db){this.db=db;}
 @GetMapping ResponseEntity<?> list(){return ResponseEntity.ok(db.query("SELECT a.id,a.patient_user_id,a.professional_id,a.location_id,a.specialty_id,a.scheduled_start_at,a.scheduled_end_at,s.code status FROM appointments a JOIN appointment_statuses s ON s.id=a.status_id WHERE s.code='REQUESTED' ORDER BY a.scheduled_start_at",(r,n)->Map.of("id",r.getLong(1),"patientUserId",r.getLong(2),"professionalId",r.getLong(3),"locationId",r.getLong(4),"specialtyId",r.getLong(5),"startAt",r.getTimestamp(6).toLocalDateTime(),"endAt",r.getTimestamp(7).toLocalDateTime(),"status",r.getString(8))));}
 @PatchMapping("/{id}") @Transactional ResponseEntity<?> decide(@PathVariable long id,@RequestBody Decision d,Authentication a){if(d==null||(!"APPROVED".equals(d.status())&&!"REJECTED".equals(d.status())))return ResponseEntity.badRequest().body(Map.of("message","decisión inválida")); if("REJECTED".equals(d.status())&&(d.reason()==null||d.reason().isBlank()))return ResponseEntity.badRequest().body(Map.of("message","motivo requerido")); var rows=db.queryForList("SELECT a.id,s.id status_id FROM appointments a JOIN appointment_statuses s ON s.code=? WHERE a.id=?", "REQUESTED",id); if(rows.isEmpty())return ResponseEntity.notFound().build(); int n=db.update("UPDATE appointments SET status_id=(SELECT id FROM appointment_statuses WHERE code=?),approved_by_user_id=CASE WHEN ?='APPROVED' THEN ? ELSE NULL END,approved_at=CASE WHEN ?='APPROVED' THEN CURRENT_TIMESTAMP ELSE NULL END,updated_at=CURRENT_TIMESTAMP WHERE id=?",d.status(),d.status(),Long.parseLong(a.getName()),d.status(),id); if("REJECTED".equals(d.status()))db.update("UPDATE professional_slots SET appointment_id=NULL WHERE appointment_id=?",id); return ResponseEntity.ok(Map.of("id",id,"status",d.status(),"reason",d.reason()==null?"":d.reason()));}
 record Decision(String status,String reason){}
}
